INSERT INTO public.polish_city_cases ("id", "city_key", "nominative", "genitive", "locative", "locative_preposition", "is_active") SELECT '7d938fe6-36dc-41db-af89-207304111479', 'ryn', 'Ryn', 'Rynu', 'Rynie', 'w', true WHERE NOT EXISTS (SELECT 1 FROM public.polish_city_cases WHERE "city_key" IS NOT DISTINCT FROM 'ryn');

INSERT INTO public.polish_city_cases ("id", "city_key", "nominative", "genitive", "locative", "locative_preposition", "is_active") SELECT 'b0260537-b7a1-4944-be4e-d09b5b657c60', 'warchaly', 'Warchały', 'Warchał', 'Warchałach', 'w', true WHERE NOT EXISTS (SELECT 1 FROM public.polish_city_cases WHERE "city_key" IS NOT DISTINCT FROM 'warchaly');

INSERT INTO public.seo_city_content ("id", "page_slug", "city", "region", "custom_title", "custom_description", "custom_h1", "local_features", "is_active") SELECT '7f405fc6-42a4-45c9-a1fb-494c9785e983', 'wieczory-tematyczne', 'ryn', 'warmińsko-mazurskie', 'Imprezy tematyczne Ryn — wieczory dla firm | MAVINCI', 'Wieczory tematyczne i integracje dla firm w Rynie. Gatsby, Hollywood lub Las Vegas po konferencji: DJ, prowadzenie, dekoracje i technika MAVINCI.', 'Imprezy i wieczory tematyczne dla firm w Rynie', '{"intro_heading": "Ryn: od konferencji do bankietu z motywem przewodnim", "intro_text": "Ryn łączy mazurskie otoczenie jezior Ryńskiego i Ołów z historyczną zabudową. Przy planowaniu firmowego wieczoru warto wykorzystać charakter wybranej sali. Gatsby może nadać kierunek jubileuszowi, Hollywood — wręczeniu wyróżnień, a Las Vegas — swobodnym rozmowom przy stołach kasyna rozrywkowego. Motyw dobieramy do celu spotkania, a nie samej dekoracji. Możemy połączyć prowadzenie, DJ-a, quiz o firmie i wybrane atrakcje w scenariusz, który zaczyna się po zakończeniu konferencji.", "planning_heading": "Plan sali i przejście z części biznesowej do wieczoru", "planning_text": "Przy wydarzeniu w Rynie ustalamy, czy kolacja i konferencja korzystają z jednej przestrzeni. Jeżeli tak, montaż dekoracji i próbę muzyczną trzeba zmieścić w uzgodnionej przerwie albo przygotować wcześniej osobną strefę. W obiekcie historycznym pytamy gospodarza o możliwości mocowania dekoracji, trasę wniesienia urządzeń i użycie efektów. Przyjeżdżamy z zaplecza w Olsztynie; transport, realizatorów i godziny pracy wpisujemy do oferty. Wybór obiektu i dostępność sali pozostają osobnym ustaleniem z organizatorem.", "planning_checks": ["Rzut sali z miejscem na stoły bankietowe, parkiet i atrakcje.", "Czas między ostatnią prezentacją a wejściem gości na kolację.", "Zgoda obiektu na wybraną dekorację, światło i efekty.", "Droga wniesienia stołów kasynowych oraz godziny demontażu."], "faq": [{"question": "Jaki motyw wybrać na bankiet firmowy w Rynie?", "answer": "Do jubileuszu można dopasować Gatsby, do gali z nagrodami Hollywood, a do wieczoru nastawionego na rozmowy Las Vegas. Są to propozycje scenariusza. Ostateczny wybór zależy od uczestników, aranżacji sali i czasu programu; zakres dekoracji i atrakcji określamy w ofercie."}, {"question": "Czy można zorganizować wieczór w tej samej sali co konferencję?", "answer": "Tak, jeśli obiekt udostępnia czas na zmianę ustawienia i próby. Przygotowujemy plan przejścia z prezentacji do bankietu: ustawienie techniki, sceny świetlne, materiały na ekranie i rozpoczęcie programu. Gdy przerwa jest zbyt krótka, uzgadniamy oddzielną strefę lub mniejszy zakres przebudowy."}, {"question": "Czy macie stały lokal lub własny hotel w Rynie?", "answer": "Nasze biuro i magazyn znajdują się w Olsztynie przy Towarowej 20B. Do Rynu przyjeżdżamy na wydarzenie w miejscu wskazanym przez organizatora. Nie reprezentujemy hoteli ani nie gwarantujemy ich dostępności; warunki pracy ustalamy z wybranym obiektem."}, {"question": "Co przesłać do wyceny wieczoru w Rynie?", "answer": "Termin, nazwę obiektu, liczbę uczestników, program konferencji lub kolacji, wybrany motyw i budżet. Pomocne będą plan sali oraz godziny dostępu dla ekipy. Na tej podstawie określamy atrakcje, technikę, transport i obsługę."}], "lead": "Bankiet po konferencji, jubileusz czy integracja z noclegiem w Rynie? Przygotowujemy motyw, program dla gości, muzykę i oprawę sali. Dobieramy dekoracje, światło i nagłośnienie do wybranego obiektu oraz czasu dostępnego na montaż."}'::jsonb, true WHERE NOT EXISTS (SELECT 1 FROM public.seo_city_content WHERE "page_slug" IS NOT DISTINCT FROM 'wieczory-tematyczne' AND "city" IS NOT DISTINCT FROM 'ryn');

INSERT INTO public.seo_city_content ("id", "page_slug", "city", "region", "custom_title", "custom_description", "custom_h1", "local_features", "is_active") SELECT 'c044e1d8-9a13-42b0-9f11-d6f53b10da97', 'wieczory-tematyczne', 'gizycko', 'warmińsko-mazurskie', 'Imprezy tematyczne Giżycko — integracje firmowe | MAVINCI', 'Integracja tematyczna w Giżycku: wieczór po programie nad jeziorami, DJ, quiz, kasyno rozrywkowe i własna technika. Zaplanuj imprezę firmową z MAVINCI.', 'Imprezy i wieczory tematyczne dla firm w Giżycku', '{"intro_heading": "Wieczorna integracja po dniu nad mazurskimi jeziorami", "intro_text": "Giżycko nad Niegocinem pozwala połączyć pobyt firmowy z programem wokół jezior. Jeśli organizator przewidział rejs lub aktywności na zewnątrz, część wieczorna powinna uwzględniać powrót uczestników, kolację i czas na odpoczynek. Proponujemy łagodne rozpoczęcie od muzyki i rozmów, następnie wspólny quiz lub teleturniej, a później parkiet. Motyw disco, Gatsby albo Las Vegas porządkuje oprawę, bez konieczności angażowania każdego uczestnika w obowiązkowe konkurencje. Aktywności dzienne i transport gości uzgadniamy oddzielnie.", "planning_heading": "Hotel, strefa zewnętrzna i jeden harmonogram wieczoru", "planning_text": "Dla wydarzenia w Giżycku potrzebujemy dokładnego obiektu, nie tylko nazwy miasta. Gdy program obejmuje taras, teren nad jeziorem i salę, określamy, które punkty odbywają się w każdej strefie i kiedy goście się przemieszczają. Wariant na deszcz ustalamy z gospodarzem przed montażem. Nagłośnienie, oświetlenie oraz ekran dobieramy do warunków pracy i zasad obiektu. Zaplecze MAVINCI jest w Olsztynie; dojazd zespołu i urządzeń planujemy niezależnie od transportu uczestników.", "planning_checks": ["Godzina powrotu grupy z programu dziennego i rozpoczęcia kolacji.", "Rozdzielenie stref rozmów, atrakcji i parkietu.", "Sala rezerwowa dla elementów zaplanowanych na zewnątrz.", "Zasilanie, droga transportu urządzeń oraz zasady głośności."], "faq": [{"question": "Czy wieczór w Giżycku może odbyć się po rejsie firmowym?", "answer": "Tak. Dopasowujemy start muzyki i części prowadzonej do powrotu grupy oraz kolacji. Warto przewidzieć bufor w harmonogramie. Rejs i przewóz uczestników nie są automatycznie częścią zamówienia wieczoru tematycznego."}, {"question": "Czy można połączyć imprezę w sali i nad jeziorem?", "answer": "Można zaplanować dwa miejsca programu, jeśli obiekt na to pozwala. Osobno ustalamy zasilanie, nagłośnienie, ochronę urządzeń oraz moment przejścia gości do sali. Przed wydarzeniem potrzebny jest wariant pogodowy i osoba zatwierdzająca zmianę programu."}, {"question": "Jak zintegrować pracowników, którzy nie chcą tańczyć?", "answer": "Możemy zaproponować krótkie rundy quizu, teleturniej drużynowy lub strefę kasyna rozrywkowego. Te elementy pozwalają dołączyć do zabawy w różnym tempie. Uzgadniamy także miejsce na spokojne rozmowy poza bezpośrednim sąsiedztwem parkietu."}, {"question": "Czy przyjeżdżacie z własną techniką do Giżycka?", "answer": "Tak. Własne nagłośnienie Meyer Sound, światło i multimedia dobieramy do programu. Zakres oraz dostępność sprzętu, montaż, transport z Olsztyna i obsługę potwierdzamy w indywidualnej ofercie."}], "lead": "Po dniu spotkań lub aktywności na Mazurach zaproś zespół na wspólny wieczór w Giżycku. Motyw imprezy łączymy z muzyką, prowadzeniem i atrakcjami, a technikę oraz czas rozpoczęcia dopasowujemy do planu całego wyjazdu."}'::jsonb, true WHERE NOT EXISTS (SELECT 1 FROM public.seo_city_content WHERE "page_slug" IS NOT DISTINCT FROM 'wieczory-tematyczne' AND "city" IS NOT DISTINCT FROM 'gizycko');

INSERT INTO public.seo_city_content ("id", "page_slug", "city", "region", "custom_title", "custom_description", "custom_h1", "local_features", "is_active") SELECT '1144f5f3-4cf8-41ee-b3cf-0b74dd841adb', 'wieczory-tematyczne', 'elk', 'warmińsko-mazurskie', 'Imprezy tematyczne Ełk — wieczory i gale firmowe | MAVINCI', 'Wieczory tematyczne dla firm w Ełku: integracje, jubileusze i gale z DJ-em, prowadzeniem, dekoracjami oraz multimediami. Poznaj propozycje MAVINCI.', 'Imprezy i wieczory tematyczne dla firm w Ełku', '{"intro_heading": "Ełk: firmowe podziękowania i wspólna zabawa w jednym scenariuszu", "intro_text": "Przy spotkaniu pracowników w Ełku motyw wieczoru może wynikać z okazji: jubileuszu, zakończenia projektu albo podsumowania roku. Hollywood daje ramy dla wręczenia wyróżnień i prezentacji zespołów, a muzyczny wieczór retro może połączyć osoby z różnych działów. Możemy przygotować prowadzenie oraz quiz oparty na materiałach firmy. Jeśli plan pobytu obejmuje spacer nad Jeziorem Ełckim, organizator może potraktować go jako spokojne wprowadzenie przed kolacją; część prowadzoną rozpoczynamy po zebraniu grupy.", "planning_heading": "Scenariusz gali, materiały na ekran i wejścia prowadzącego", "planning_text": "W Ełku zaczynamy przygotowania od listy punktów programu oraz planu wybranej sali. Przy gali ustalamy kolejność wystąpień, sposób zapowiadania nagrodzonych, oprawę muzyczną i pliki wyświetlane na ekranie. Przed wejściem gości potrzebujemy czasu na sprawdzenie nazwisk, prezentacji i mikrofonów. Część taneczna lub kasyno rozrywkowe może rozpocząć się po zamknięciu oficjalnego programu. Dojazd z Olsztyna, transport dekoracji i techniki oraz demontaż uwzględniamy w uzgodnionym zakresie.", "planning_checks": ["Kolejność przemówień, wyróżnień i części integracyjnej.", "Lista nazwisk, logotypy oraz zatwierdzone pliki do wyświetlenia.", "Miejsce prowadzącego, widoczność ekranu i droga wejścia na scenę.", "Czas na próbę przed kolacją i warunki zakończenia imprezy."], "faq": [{"question": "Czy przygotujecie galę firmową w Ełku w stylu Hollywood?", "answer": "Możemy oprzeć scenariusz na filmowej oprawie, zapowiedziach prowadzącego i wręczeniu firmowych wyróżnień. Organizator dostarcza zatwierdzoną listę osób oraz materiały firmy. Dekoracje, ekran, oświetlenie i ewentualne występy wybieramy do konkretnej sali i budżetu."}, {"question": "Czy quiz podczas integracji może dotyczyć naszej firmy?", "answer": "Tak, po otrzymaniu materiałów możemy uzgodnić pytania nawiązujące do historii firmy, zespołów i projektów. Treść wymaga akceptacji organizatora. Dobieramy formę gry do liczby osób i czasu dostępnego w programie."}, {"question": "Czy możecie obsłużyć imprezę w siedzibie firmy w Ełku?", "answer": "Tak, o ile przestrzeń pozwala na uzgodniony format. Przed ofertą potrzebujemy informacji o powierzchni, wejściu technicznym, zasilaniu, ustawieniu gości i zasadach korzystania z budynku. Nie trzeba wybierać hotelu, aby zamówić oprawę wieczoru."}, {"question": "Czy wszystkie atrakcje są w jednym pakiecie?", "answer": "Zakres ustalamy indywidualnie: scenariusz, muzyka, prowadzenie, dekoracje, technika i wybrane atrakcje są wyszczególnione w ofercie. Wynajem sali, catering i noclegi wymagają osobnych uzgodnień."}], "lead": "Spotkanie zespołu, jubileusz lub gala z podziękowaniami w Ełku mogą mieć jeden spójny motyw. Przygotowujemy przebieg wieczoru, muzykę, atrakcje i własną technikę, z miejscem zarówno na część oficjalną, jak i swobodną integrację."}'::jsonb, true WHERE NOT EXISTS (SELECT 1 FROM public.seo_city_content WHERE "page_slug" IS NOT DISTINCT FROM 'wieczory-tematyczne' AND "city" IS NOT DISTINCT FROM 'elk');

INSERT INTO public.seo_city_content ("id", "page_slug", "city", "region", "custom_title", "custom_description", "custom_h1", "local_features", "is_active") SELECT '7cfa0860-844c-459f-a3aa-f034269e8a67', 'wieczory-tematyczne', 'warchaly', 'warmińsko-mazurskie', 'Imprezy tematyczne Warchały — integracje | MAVINCI', 'Imprezy tematyczne w Warchałach: wieczór podczas wyjazdu firmowego, DJ, quiz, dekoracje i własna technika. Zaplanuj integrację na Mazurach z MAVINCI.', 'Imprezy i wieczory tematyczne dla firm w Warchałach', '{"intro_heading": "Warchały: wieczór tematyczny podczas firmowego wyjazdu", "intro_text": "Warchały w gminie Jedwabno, w otoczeniu jezior Świętajno i Brajnickiego, są miejscem, w którym firmowy program może przeplatać spotkania z odpoczynkiem. Część wieczorną warto dopasować do rytmu pobytu. Po szkoleniu można rozpocząć od kolacji i krótkiego quizu, a następnie przejść do muzyki i tańca. Dla mniej formalnej integracji proponujemy motyw disco lub Aloha, a dla eleganckiego bankietu Gatsby albo Las Vegas. Dobór motywu nie wymaga obowiązkowych przebrań; klimat można stworzyć światłem, muzyką i uzgodnionymi dekoracjami.", "planning_heading": "Sala i plener w Warchałach — plan przygotowania wydarzenia", "planning_text": "Przy organizacji wieczoru w Warchałach prosimy o nazwę obiektu, wskazanie konkretnej sali oraz miejsca dostawy sprzętu. Gdy część programu ma odbywać się na tarasie lub terenie zewnętrznym, uzgadniamy z gospodarzem wariant w sali, ochronę urządzeń i zasady korzystania z nagłośnienia. Przed ofertą ustalamy też dostępność sali po szkoleniu oraz godzinę zakończenia imprezy względem pobytu pozostałych gości. Własne zaplecze przy Towarowej 20B w Olsztynie pozwala nam przygotować uzgodniony sprzęt do wyjazdu; nie mamy oddziału ani własnej sali w Warchałach.", "planning_checks": ["Nazwa sali i dokładne miejsce rozładunku na terenie obiektu.", "Czas wolny między szkoleniem, kolacją a integracją.", "Wariant w sali dla programu przewidzianego na zewnątrz.", "Zasilanie, zasady głośności i godzina zakończenia pracy ekipy."], "faq": [{"question": "Czy organizujecie wieczory tematyczne w Warchałach koło Jedwabna?", "answer": "Tak, możemy przygotować program i oprawę w obiekcie wskazanym przez organizatora w Warchałach. Przy zapytaniu podaj nazwę miejsca, datę i liczbę uczestników. Dojeżdżamy z biura i magazynu w Olsztynie; transport oraz dostępność potwierdzamy w ofercie."}, {"question": "Jaka integracja sprawdzi się po szkoleniu podczas wyjazdu do Warchał?", "answer": "Można zaplanować krótki quiz drużynowy po kolacji, potem swobodne korzystanie z atrakcji i część muzyczną. Jeśli grupa ma intensywny dzień, proponujemy mniej punktów prowadzonych i więcej czasu na rozmowy. Ostateczny program uzgadniamy z organizatorem."}, {"question": "Czy impreza może rozpocząć się na tarasie, a zakończyć w sali?", "answer": "Tak, jeśli pozwalają na to zasady obiektu i dostępne przestrzenie. Plan obejmuje wtedy dwie strefy, godziny przejścia i sposób przeniesienia lub osobnego przygotowania techniki. Warunki pogodowe i wariant w sali ustalamy przed wydarzeniem."}, {"question": "Czy organizacja obejmuje rezerwację noclegów i kolacji?", "answer": "Ta oferta dotyczy programu, oprawy i uzgodnionych atrakcji. Noclegi, catering oraz rezerwację sali ustalamy osobno z organizatorem i wybranym obiektem. Przygotowanie wieczoru nie oznacza potwierdzenia dostępności hotelu."}], "lead": "Wyjazd firmowy do Warchał może łączyć szkolenie, odpoczynek i wspólny wieczór. Dopasowujemy motyw, DJ-a, prowadzenie i atrakcje do grupy, a sprzęt do sali lub uzgodnionej przestrzeni zewnętrznej."}'::jsonb, true WHERE NOT EXISTS (SELECT 1 FROM public.seo_city_content WHERE "page_slug" IS NOT DISTINCT FROM 'wieczory-tematyczne' AND "city" IS NOT DISTINCT FROM 'warchaly');

INSERT INTO public.schema_org_places ("id", "business_id", "name", "locality", "postal_code", "region", "country", "display_order", "is_active", "is_global") SELECT 'ddc69b97-7af3-428c-8bb6-c24688e99130', NULL, 'Ryn', 'ryn', NULL, 'Województwo Warmińsko-Mazurskie', 'PL', 38, true, true WHERE NOT EXISTS (SELECT 1 FROM public.schema_org_places WHERE "locality" IS NOT DISTINCT FROM 'ryn' AND "is_global" IS NOT DISTINCT FROM true);

INSERT INTO public.schema_org_places ("id", "business_id", "name", "locality", "postal_code", "region", "country", "display_order", "is_active", "is_global") SELECT 'f793f6e8-cf4c-4af2-bcf9-d643c2d4de0c', NULL, 'Warchały', 'warchaly', NULL, 'Województwo Warmińsko-Mazurskie', 'PL', 39, true, true WHERE NOT EXISTS (SELECT 1 FROM public.schema_org_places WHERE "locality" IS NOT DISTINCT FROM 'warchaly' AND "is_global" IS NOT DISTINCT FROM true);

